use ai_home::{application::Application,persistence::Store};
use serde_json::{json,Value};
use sha2::{Digest,Sha256};
use std::{io::Read,path::PathBuf};
fn dir()->PathBuf{let p=std::env::temp_dir().join(format!("ai-home-export-{}",uuid::Uuid::new_v4()));std::fs::create_dir_all(&p).unwrap();p}
fn req(id:&str,command:&str,payload:Value,profile:Option<&str>)->Value{let mut v=json!({"contractVersion":1,"requestId":id,"command":command,"payload":payload});if let Some(p)=profile{v["profileId"]=json!(p)}v}
#[tokio::test]
async fn portable_export_keeps_order_and_excludes_private_provider_state(){
 let d=dir();let db=d.join("foundation.sqlite3");let store=Store::open(&db).await.unwrap();let app=Application::new(store);
 let p=app.dispatch(req("p","profile.create",json!({"displayName":"Export Test"}),None)).await.response;assert_eq!(p["ok"],true);let pid=p["result"]["id"].as_str().unwrap().to_string();
 let c=app.dispatch(req("c","conversation.create",json!({"title":"Hello / świat","language":"pl"}),Some(&pid))).await.response;assert_eq!(c["ok"],true);let cid=c["result"]["id"].as_str().unwrap().to_string();
 let m1=json!({"schemaVersion":1,"id":"m1","profileId":pid,"revision":1,"createdAt":"2026-10-23T10:00:00Z","conversationId":cid,"sequence":1,"role":"human","content":"Pierwsza wiadomość","language":"pl","status":"complete","sourceRefs":[]});
 let m2=json!({"schemaVersion":1,"id":"m2","profileId":pid,"revision":1,"createdAt":"2026-10-23T10:01:00Z","conversationId":cid,"sequence":2,"role":"assistant","content":"Druga odpowiedź","language":"pl","status":"complete","sourceRefs":[]});
 sqlx::query("INSERT INTO messages(profile_id,id,conversation_id,sequence,revision,body) VALUES(?,?,?,?,1,?),(?,?,?,?,1,?)").bind(&pid).bind("m1").bind(&cid).bind(1i64).bind(m1.to_string()).bind(&pid).bind("m2").bind(&cid).bind(2i64).bind(m2.to_string()).execute(&app_store_pool(&db).await).await.unwrap();
 sqlx::query("INSERT INTO chat_replay(profile_id,message_id,scope,body) VALUES(?,?,?,?)").bind(&pid).bind("m2").bind("private").bind(r#"{"secret":"DO_NOT_EXPORT"}"#).execute(&app_store_pool(&db).await).await.unwrap();
 let ex=app.dispatch(req("export-once","profile.export.create",json!({}),Some(&pid))).await.response;assert_eq!(ex["ok"],true,"{ex}");let eid=ex["result"]["id"].as_str().unwrap();let zip_path=d.join("exports").join(&pid).join(format!("{eid}.zip"));assert!(zip_path.is_file());
 let f=std::fs::File::open(zip_path).unwrap();let mut z=zip::ZipArchive::new(f).unwrap();let names:Vec<String>=(0..z.len()).map(|i|z.by_index(i).unwrap().name().to_string()).collect();assert!(names.iter().any(|n|n.starts_with("conversations/")&&n.ends_with(".md")));assert!(names.contains(&"manifest.json".to_string()));assert!(!names.iter().any(|n|n.contains("replay")||n.contains("credential")||n.contains("receipt")));
 let mdname=names.iter().find(|n|n.starts_with("conversations/")).unwrap().clone();let mut md=String::new();z.by_name(&mdname).unwrap().read_to_string(&mut md).unwrap();assert!(md.find("Pierwsza wiadomość").unwrap()<md.find("Druga odpowiedź").unwrap());
 let mut all=String::new();for i in 0..z.len(){let mut e=z.by_index(i).unwrap();if !e.is_file(){continue}let mut b=Vec::new();e.read_to_end(&mut b).unwrap();all.push_str(&String::from_utf8_lossy(&b));}assert!(!all.contains("DO_NOT_EXPORT"));drop(app);let _=std::fs::remove_dir_all(d);
}
#[tokio::test]
async fn export_request_is_idempotent_and_profile_scoped(){
 let d=dir();let db=d.join("foundation.sqlite3");let store=Store::open(&db).await.unwrap();let app=Application::new(store);let p1=app.dispatch(req("p1","profile.create",json!({"displayName":"One"}),None)).await.response;let p2=app.dispatch(req("p2","profile.create",json!({"displayName":"Two"}),None)).await.response;let a=p1["result"]["id"].as_str().unwrap();let b=p2["result"]["id"].as_str().unwrap();let e1=app.dispatch(req("same-export","profile.export.create",json!({}),Some(a))).await.response;let e2=app.dispatch(req("same-export","profile.export.create",json!({}),Some(a))).await.response;assert_eq!(e1["result"]["id"],e2["result"]["id"]);let list=app.dispatch(req("list","profile.export.list",json!({}),Some(b))).await.response;assert_eq!(list["result"]["items"].as_array().unwrap().len(),0);drop(app);let _=std::fs::remove_dir_all(d);
}
async fn app_store_pool(path:&std::path::Path)->sqlx::SqlitePool{use sqlx::sqlite::{SqliteConnectOptions,SqlitePoolOptions};SqlitePoolOptions::new().max_connections(1).connect_with(SqliteConnectOptions::new().filename(path)).await.unwrap()}
#[tokio::test]
async fn portable_export_resolves_routes_and_memory_decisions_without_credentials(){
 let d=dir();let db=d.join("foundation.sqlite3");let store=Store::open(&db).await.unwrap();let app=Application::new(store);let p=app.dispatch(req("p-config","profile.create",json!({"displayName":"Configured"}),None)).await.response;let pid=p["result"]["id"].as_str().unwrap().to_string();let pool=app_store_pool(&db).await;
 let conn=json!({"schemaVersion":1,"id":"conn-export","profileId":pid,"revision":1,"createdAt":"2026-10-23T10:00:00Z","providerKind":"custom_openai","normalizedEndpoint":"https://example.invalid/v1","credentialRef":"SECRET-REF-MUST-NOT-EXPORT","credentialRevision":3,"label":"Portable connection","status":"unverified"});
 let route=json!({"schemaVersion":1,"id":"route-export","profileId":pid,"revision":1,"createdAt":"2026-10-23T10:00:00Z","role":"primary","connectionId":"conn-export","modelId":"model-export","outputLimitTokens":1024});
 sqlx::query("INSERT INTO connections(profile_id,id,revision,body) VALUES(?,?,1,?)").bind(&pid).bind("conn-export").bind(conn.to_string()).execute(&pool).await.unwrap();sqlx::query("INSERT INTO routes(profile_id,id,connection_id,revision,body) VALUES(?,?,?,1,?)").bind(&pid).bind("route-export").bind("conn-export").bind(route.to_string()).execute(&pool).await.unwrap();
 let mut pb=p["result"].clone();pb["primaryRouteId"]=json!("route-export");pb["revision"]=json!(pb["revision"].as_i64().unwrap()+1);sqlx::query("UPDATE profiles SET revision=?,body=? WHERE id=?").bind(pb["revision"].as_i64().unwrap()).bind(pb.to_string()).bind(&pid).execute(&pool).await.unwrap();
 let op=json!({"id":"op-export","profileId":pid,"revision":1,"status":"succeeded"});sqlx::query("INSERT INTO operations(profile_id,id,revision,body) VALUES(?,?,1,?)").bind(&pid).bind("op-export").bind(op.to_string()).execute(&pool).await.unwrap();let record_id=format!("working-{pid}");
 let proposal=json!({"schemaVersion":1,"id":"proposal-export","profileId":pid,"revision":1,"createdAt":"2026-10-23T10:01:00Z","operationId":"op-export","memoryRecordId":record_id,"memoryKind":"working","proposerRole":"primary","proposerRouteId":"route-export","content":"approved portable fact","language":"en","sources":[],"state":"decided","capacityPolicySnapshot":{"maxAttempts":2,"outputTokens":1024},"attemptNumber":1,"claimKind":"fact"});
 let decision=json!({"schemaVersion":1,"id":"decision-export","profileId":pid,"revision":1,"createdAt":"2026-10-23T10:02:00Z","operationId":"op-export","proposalId":"proposal-export","primaryRouteId":"route-export","routeRevision":1,"decision":"accept","candidateSha256":"a".repeat(64),"candidateMeasurement":{"method":"utf8_bytes_estimate","value":10},"reason":"approved"});
 let version=json!({"schemaVersion":1,"id":"version-export","profileId":pid,"revision":1,"createdAt":"2026-10-23T10:03:00Z","recordId":record_id,"versionNumber":1,"content":"approved portable fact","language":"en","contentSha256":"a".repeat(64),"measurement":{"method":"utf8_bytes_estimate","value":10},"sources":[],"origin":"agent_decision","decisionReceiptId":"decision-export","claimKind":"fact"});
 sqlx::query("INSERT INTO memory_proposals(profile_id,id,revision,body) VALUES(?,?,1,?)").bind(&pid).bind("proposal-export").bind(proposal.to_string()).execute(&pool).await.unwrap();sqlx::query("INSERT INTO memory_decisions(profile_id,id,revision,body) VALUES(?,?,1,?)").bind(&pid).bind("decision-export").bind(decision.to_string()).execute(&pool).await.unwrap();sqlx::query("INSERT INTO memory_versions(profile_id,id,revision,body) VALUES(?,?,1,?)").bind(&pid).bind("version-export").bind(version.to_string()).execute(&pool).await.unwrap();
 let ex=app.dispatch(req("export-configured","profile.export.create",json!({}),Some(&pid))).await.response;assert_eq!(ex["ok"],true,"{ex}");let eid=ex["result"]["id"].as_str().unwrap();let f=std::fs::File::open(d.join("exports").join(&pid).join(format!("{eid}.zip"))).unwrap();let mut z=zip::ZipArchive::new(f).unwrap();let mut connections=String::new();z.by_name("data/connections.portable.json").unwrap().read_to_string(&mut connections).unwrap();assert!(!connections.contains("credentialRef"));assert!(!connections.contains("SECRET-REF-MUST-NOT-EXPORT"));assert!(connections.contains("requiresCredentialRebind"));let mut routes=String::new();z.by_name("data/routes.json").unwrap().read_to_string(&mut routes).unwrap();assert!(routes.contains("route-export"));let mut decisions=String::new();z.by_name("data/memory-decisions.json").unwrap().read_to_string(&mut decisions).unwrap();let mut proposals=String::new();z.by_name("data/memory-proposals.json").unwrap().read_to_string(&mut proposals).unwrap();let mut versions=String::new();z.by_name("data/memory-versions.json").unwrap().read_to_string(&mut versions).unwrap();assert!(versions.contains("decision-export"));assert!(decisions.contains("proposal-export"));assert!(proposals.contains("proposal-export"));drop(app);let _=std::fs::remove_dir_all(d);
}
#[tokio::test]
async fn export_manifest_hashes_entries_and_keeps_original_source_bytes(){
 let d=dir();let db=d.join("foundation.sqlite3");let store=Store::open(&db).await.unwrap();let app=Application::new(store);let p=app.dispatch(req("p-source","profile.create",json!({"displayName":"Sources"}),None)).await.response;let pid=p["result"]["id"].as_str().unwrap().to_string();let pool=app_store_pool(&db).await;let source=b"portable-original-source\x00\xff".to_vec();let sha=format!("{:x}",Sha256::digest(&source));let op=json!({"id":"op-source","profileId":pid,"revision":1,"status":"succeeded"});sqlx::query("INSERT INTO operations(profile_id,id,revision,body) VALUES(?,?,1,?)").bind(&pid).bind("op-source").bind(op.to_string()).execute(&pool).await.unwrap();sqlx::query("INSERT INTO import_blobs(profile_id,id,sha256,bytes) VALUES(?,?,?,?)").bind(&pid).bind("blob-source").bind(&sha).bind(&source).execute(&pool).await.unwrap();let material=json!({"id":"material-source","profileId":pid,"revision":1,"operationId":"op-source","originalBlobId":"blob-source"});sqlx::query("INSERT INTO profile_import_materials(profile_id,id,operation_id,original_blob_id,revision,body) VALUES(?,?,?,?,1,?)").bind(&pid).bind("material-source").bind("op-source").bind("blob-source").bind(material.to_string()).execute(&pool).await.unwrap();let ex=app.dispatch(req("export-source","profile.export.create",json!({}),Some(&pid))).await.response;assert_eq!(ex["ok"],true,"{ex}");let eid=ex["result"]["id"].as_str().unwrap();let f=std::fs::File::open(d.join("exports").join(&pid).join(format!("{eid}.zip"))).unwrap();let mut z=zip::ZipArchive::new(f).unwrap();let source_name=format!("sources/blob-source-{sha}.bin");let mut got=Vec::new();z.by_name(&source_name).unwrap().read_to_end(&mut got).unwrap();assert_eq!(got,source);let mut manifest_text=String::new();z.by_name("manifest.json").unwrap().read_to_string(&mut manifest_text).unwrap();let manifest:Value=serde_json::from_str(&manifest_text).unwrap();for entry in manifest["entries"].as_array().unwrap(){let name=entry["name"].as_str().unwrap();let mut bytes=Vec::new();z.by_name(name).unwrap().read_to_end(&mut bytes).unwrap();assert_eq!(entry["sizeBytes"].as_u64(),Some(bytes.len() as u64),"{name}");let expected_sha=format!("{:x}",Sha256::digest(&bytes));assert_eq!(entry["sha256"].as_str(),Some(expected_sha.as_str()),"{name}");}drop(app);let _=std::fs::remove_dir_all(d);
}
